func tl0(a *tslabs, v any) []*Arg {
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []*Arg{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl0Chunk, len(n.kids))
	for i, c := range n.kids {
		out[i] = tAs[*Arg](c)
	}
	return out
}

